#include <stdio.h>
#include <stdlib.h>
#include <string.h>

long long gcd(long long a, long long b) {
    while(b) { long long t = b; b = a%b; a = t; }
    return a;
}

long long lcm(long long a, long long b) {
    return a / gcd(a,b) * b;
}

// CRT: find x such that x ≡ r1 (mod m1) and x ≡ r2 (mod m2)
// Returns 0 if no solution, 1 if solution found (updates r1, m1)
int crt(long long *r1, long long *m1, long long r2, long long m2) {
    long long g = gcd(*m1, m2);
    if ((r2 - *r1) % g != 0) return 0;
    long long lcm_val = lcm(*m1, m2);
    // x = r1 + m1*t, need r1 + m1*t ≡ r2 (mod m2)
    // m1*t ≡ (r2-r1) (mod m2)
    // (m1/g)*t ≡ (r2-r1)/g (mod m2/g)
    long long m1g = *m1/g, m2g = m2/g, rg = (r2 - *r1)/g % m2g;
    if(rg < 0) rg += m2g;
    // find inverse of m1g mod m2g
    // extended gcd
    long long a = m1g % m2g, b = m2g;
    long long x0 = 1, x1 = 0;
    long long aa = a, bb = b;
    while(bb) { long long q = aa/bb, t = bb; bb = aa - q*bb; aa = t; t = x1; x1 = x0 - q*x1; x0 = t; }
    // x0 is inverse of a mod b (original b = m2g)
    long long inv = x0 % m2g;
    if(inv < 0) inv += m2g;
    long long t = (rg * inv) % m2g;
    *r1 = *r1 + *m1 * t;
    *m1 = lcm_val;
    *r1 = ((*r1) % *m1 + *m1) % *m1;
    return 1;
}

