typedef long long ll;

static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static ll lcm_limit(ll a, ll b, ll limit) {
    ll g = gcdll(a, b);
    a /= g;
    if (a > limit / b) return limit + 1;
    return a * b;
}

static ll exgcd(ll a, ll b, ll *x, ll *y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }
    ll x1, y1;
    ll g = exgcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

/* Solve:
   t ≡ a1 (mod m1)
   t ≡ a2 (mod m2)
   Return smallest non-negative solution in *res and lcm in *mod.
   Return 0 if impossible.
*/
static int crt_merge(ll a1, ll m1, ll a2, ll m2, ll *res, ll *mod, ll limit) {
    if (m1 == 0 || m2 == 0) return 0;
    ll x, y;
    ll g = exgcd(m1, m2, &x, &y);
    ll diff = a2 - a1;
    if (diff % g != 0) return 0;

    ll m2g = m2 / g;
    ll k = diff / g;

    __int128 xx = x;
    __int128 kk = k;
    ll mult = (ll)((xx * kk % m2g + m2g) % m2g);

    __int128 ans = (__int128)a1 + (__int128)m1 * mult;
    ll l = lcm_limit(m1, m2, limit);
    if (l > limit) return 0;

    ll ansmod = (ll)(ans % l);
    if (ansmod < 0) ansmod += l;

    *res = ansmod;
    *mod = l;
    return 1;
}

