typedef long long ll;

ll gcd(ll a, ll b) { return b == 0 ? a : gcd(b, a % b); }

// Returns x such that a*x ≡ 1 (mod m), or -1 if not exists
ll mod_inv(ll a, ll m) {
    ll g = gcd(a, m);
    if (g != 1) return -1;
    // Extended gcd
    ll x = 1, y = 0, x1 = 0, y1 = 1, a0 = a, m0 = m;
    while (m) { ll q = a/m; tie(a,m)=make_tuple(m,a%m); tie(x,x1)=make_tuple(x1,x-q*x1); tie(y,y1)=make_tuple(y1,y-q*y1); }
    return (x % m0 + m0) % m0;
}

// CRT: find x such that x ≡ r1 (mod m1) and x ≡ r2 (mod m2)
// Returns {r, m} or {-1, -1} if no solution
pair<ll,ll> crt(ll r1, ll m1, ll r2, ll m2) {
    ll g = gcd(m1, m2);
    if ((r2 - r1) % g != 0) return {-1, -1};
    ll lcm = m1 / g * m2;
    ll diff = (r2 - r1) / g;
    ll m1g = m1 / g;
    ll inv = mod_inv(m1g % (m2/g), m2/g);
    ll k = (diff % (m2/g) * inv) % (m2/g);
    ll r = r1 + m1 * k;
    r = ((r % lcm) + lcm) % lcm;
    return {r, lcm};
}

