int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> P(N + 1), Q(N + 1);
    for (int i = 1; i <= N; ++i) cin >> P[i];
    for (int i = 1; i <= N; ++i) cin >> Q[i];

    // Decompose Q into cycles.
    vector<int> comp(N + 1, -1), pos(N + 1, -1);
    vector<vector<int>> cycles;

    for (int i = 1; i <= N; ++i) {
        if (comp[i] != -1) continue;
        vector<int> cyc;
        int cur = i;
        int id = (int)cycles.size();
        while (comp[cur] == -1) {
            comp[cur] = id;
            pos[cur] = (int)cyc.size();
            cyc.push_back(cur);
            cur = Q[cur];
        }
        cycles.push_back(cyc);
    }

    // For each cycle, all elements appearing in positions belonging to this cycle
    // must require the same shift d modulo cycle_length.
    // Specifically, if P[i] and i are in the same cycle, then
    // Q^d(P[i]) = i  => d ≡ pos[i] - pos[P[i]] (mod len)
    // If for some i, P[i] is in a different cycle from i, impossible.
    vector<int> rems;      // required remainder for each cycle
    vector<int> mods;      // cycle lengths

    for (int cid = 0; cid < (int)cycles.size(); ++cid) {
        int len = (int)cycles[cid].size();
        int need = -1;

        for (int x : cycles[cid]) {
            int y = P[x];
            if (comp[y] != cid) {
                cout << -1 << '\n';
                return 0;
            }
            int curNeed = pos[x] - pos[y];
            curNeed %= len;
            if (curNeed < 0) curNeed += len;

            if (need == -1) need = curNeed;
            else if (need != curNeed) {
                cout << -1 << '\n';
                return 0;
            }
        }

        rems.push_back(need == -1 ? 0 : need);
        mods.push_back(len);
    }

    // Solve system:
    // d ≡ rems[i] (mod mods[i]) for all i
    // using generalized CRT.

    ll r = 0;  // current solution
    ll m = 1;  // current modulus

    auto extgcd = [&](auto&& self, ll a, ll b) -> pair<ll,ll> {
        if (b == 0) return {1, 0};
        auto [x, y] = self(self, b, a % b);
        return {y, x - (a / b) * y};
    };

    for (int i = 0; i < (int)mods.size(); ++i) {
        ll a = m, b = mods[i];
        ll c = rems[i] - r;

        ll g = std::gcd(a, b);
        if (c % g != 0) {
            cout << -1 << '\n';
            return 0;
        }

        ll a2 = a / g, b2 = b / g, c2 = c / g;

        auto [x, y] = extgcd(extgcd, a2, b2);
        ll inv = (x % b2 + b2) % b2;

        ll t = (__int128)(c2 % b2 + b2) % b2 * inv % b2;
        r = r + a * t;
        m = a / g * b;
        r %= m;
        if (r < 0) r += m;
    }

    cout << r << '\n';
    return 0;
}

