            // We'll handle by storing all constraints and combining via LCM.
        }

        // Recompute properly with CRT across cycles
        // Let's redo correctly:
        visited = new boolean[n];
        long d = 0;
        long lcm = 1;
        possible = true;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            List<Integer> cycle = new ArrayList<>();
            int cur = i;
            while (!visited[cur]) {
                visited[cur] = true;
                cycle.add(cur);
                cur = Q[cur];
            }
            int len = cycle.size();
            // map value -> index in cycle
            int[] valToIdx = new int[n];
            Arrays.fill(valToIdx, -1);
            for (int j = 0; j < len; j++) {
                valToIdx[cycle.get(j)] = j;
            }

            Integer reqRem = null;
            for (int j = 0; j < len; j++) {
                int pos = cycle.get(j);
                int val = P[pos];
                int targetIdx = valToIdx[val];
                if (targetIdx == -1) {
                    possible = false;
                    break;
                }
                int rem = (targetIdx - j + len) % len;
                if (reqRem == null) {
                    reqRem = rem;
                } else if (!reqRem.equals(rem)) {
                    possible = false;
                    break;
                }
            }
            if (!possible) break;
            if (reqRem == null) continue;

            // Combine: d ≡ reqRem (mod len)
            long[] res = crt(d, lcm, reqRem, len);
            if (res == null) {
                possible = false;
                break;
            }
            d = res[0];
            lcm = res[1];
        }

        if (!possible) {
            System.out.println(-1);
        } else {
            System.out.println(d);
        }
    }

    // Extended Euclidean Algorithm
    static long[] egcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] vals = egcd(b, a % b);
        long g = vals[0], x1 = vals[1], y1 = vals[2];
        return new long[]{g, y1, x1 - (a / b) * y1};
    }

    // Chinese Remainder Theorem for two congruences
    // x ≡ a1 (mod m1), x ≡ a2 (mod m2)
    // Returns [x, lcm] or null if impossible
    static long[] crt(long a1, long m1, long a2, long m2) {
        long[] eg = egcd(m1, m2);
        long g = eg[0], p = eg[1], q = eg[2];
        if ((a2 - a1) % g != 0) return null;
        long lcm = m1 / g * m2;
        long tmp = (a2 - a1) / g * p % (m2 / g);
        long x = (a1 + m1 * tmp) % lcm;
        if (x < 0) x += lcm;
        return new long[]{x, lcm};
    }
}

import java.util.*;

public class Main {
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] P = new int[n], Q = new int[n], R = new int[n];
        for (int i = 0; i < n; i++) { P[i] = sc.nextInt() - 1; }
        for (int i = 0; i < n; i++) { Q[i] = sc.nextInt() - 1; }
        // R = inverse of Q
        for (int i = 0; i < n; i++) R[Q[i]] = i;

        // For each i, find k_i and len_i in R's cycle
        long d = 0, mod = 1; // d ≡ 0 (mod 1) initially

        boolean[] visited = new boolean[n];
        for (int start = 0; start < n; start++) {
            if (visited[start]) continue;
            // Find cycle
            List<Integer> cycle = new ArrayList<>();
            int cur = start;
            while (!visited[cur]) {
                visited[cur] = true;
                cycle.add(cur);
                cur = R[cur];
            }
            int len = cycle.size();
            Map<Integer, Integer> posInCycle = new HashMap<>();
            for (int j = 0; j < len; j++) posInCycle.put(cycle.get(j), j);

            for (int j = 0; j < len; j++) {
                int i = cycle.get(j);
                int pi = P[i];
                if (!posInCycle.containsKey(pi)) { System.out.println(-1); return; }
                int k = (posInCycle.get(pi) - j + len) % len;
                // d ≡ k (mod len)
                long g = gcd(mod, len);
                if ((k - d % len + len * 2) % g != 0) { System.out.println(-1); return; }
                long lcm = mod / g * len;
                // Find new d
                long diff = ((k - d % len) % len + len) % len;
                // d_new = d + mod * t, need mod*t ≡ diff (mod len)
                long modG = mod / g, lenG = len / g, diffG = (diff / g) % lenG;
                long inv = modInverse(modG % lenG, lenG);
                long t = (diffG * inv) % lenG;
                d = d + mod * t;
                mod = lcm;
                d = ((d % mod) + mod) % mod;
            }
        }
        System.out.println(d);
    }

    static long modInverse(long a, long m) {
        long[] r = extgcd(a, m);
        return (r[1] % m + m) % m;
    }
    static long[] extgcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] r = extgcd(b, a % b);
        return new long[]{r[0], r[2], r[1] - (a/b)*r[2]};
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long exgcd(long a, long b, long[] xy) {
        if (b == 0) {
            xy[0] = 1;
            xy[1] = 0;
            return a;
        }
        long[] t = new long[2];
        long g = exgcd(b, a % b, t);
        xy[0] = t[1];
        xy[1] = t[0] - (a / b) * t[1];
        return g;
    }

    static long crt(long a1, long m1, long a2, long m2) {
        if (m1 == 1) return a2 % m2;
        if (m2 == 1) return a1 % m1;

        long[] xy = new long[2];
        long g = exgcd(m1, m2, xy);
        long diff = a2 - a1;
        if (diff % g != 0) return -1;

        long lcm = m1 / g * m2;

        long m2g = m2 / g;
        long k = diff / g;

        long inv = xy[0];
        long mult = modMul(mod(k, m2g), mod(inv, m2g), m2g);

        long res = (a1 + modMul(mult, m1, lcm)) % lcm;
        if (res < 0) res += lcm;
        return res;
    }

    static long mod(long a, long m) {
        long r = a % m;
        if (r < 0) r += m;
        return r;
    }

    static long modMul(long a, long b, long mod) {
        return (long)((a * 1L * b) % mod);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        int[] P = new int[N + 1];
        int[] Q = new int[N + 1];

        for (int i = 1; i <= N; i++) P[i] = fs.nextInt();
        for (int i = 1; i <= N; i++) Q[i] = fs.nextInt();

        // pos[value] = index where value currently is in P
        int[] pos = new int[N + 1];
        for (int i = 1; i <= N; i++) pos[P[i]] = i;

        // Decompose Q into cycles.
        boolean[] vis = new boolean[N + 1];
        int[] cycleId = new int[N + 1];
        int[] offset = new int[N + 1];
        ArrayList<Integer> lens = new ArrayList<>();

        int cid = 0;
        for (int x = 1; x <= N; x++) {
            if (!vis[x]) {
                ArrayList<Integer> cyc = new ArrayList<>();
                int cur = x;
                while (!vis[cur]) {
                    vis[cur] = true;
                    cyc.add(cur);
                    cur = Q[cur];
                }
                int len = cyc.size();
                for (int i = 0; i < len; i++) {
                    int v = cyc.get(i);
                    cycleId[v] = cid;
                    offset[v] = i;
                }
                lens.add(len);
                cid++;
            }
        }

        long ans = 0;
        long mod = 1;

        // For each position i, after d days value must become i.
        // If current value is v = P[i], then need Q^d(v) = i.
        // This is possible iff i and v are in same cycle of Q.
        // Then d ≡ offset[i] - offset[v] (mod cycleLen).
        for (int i = 1; i <= N; i++) {
            int v = P[i];
            if (cycleId[i] != cycleId[v]) {
                System.out.println(-1);
                return;
            }
            int len = lens.get(cycleId[i]);
            int r = offset[i] - offset[v];
            r %= len;
            if (r < 0) r += len;

            long next = crt(ans, mod, r, len);
            if (next == -1) {
                System.out.println(-1);
                return;
            }
            long g = gcd(mod, len);
            mod = mod / g * len;
            ans = next;
        }

        System.out.println(ans);
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
